head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/prelistCommon.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS2004.xml';
scwin.vBndListProcsTpCd = "1";
scwin.vMktactCd;
scwin.vBndApplId, scwin.vIsurCd;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.arrPar = new Array();
scwin.vTotAmt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.vMktactCd = scwin.arrPar[0].MKTACT_CD;
    }
};



/********************************************** 
 * 함수명   : fn_SetComboIsurNm
 * 설명       : 콤보데이터 정의 (그룹지정할 발행기관명)
 ***********************************************/
scwin.fn_SetComboIsurNm = function() {
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnscommon.select.listGroupingIsurNmIsuChg';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsurItem, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터 정의 (채권상장수수료면제사유코드)
 ***********************************************/
scwin.fn_SetComboCode = function() {
    var arrCid = [];
    arrCid.push({
        cid: '03385',
        cnm: 'cmb_BndListFeeExamCd'
    });
    arrCid.push({
        cid: '03484',
        cnm: 'cmb_YafExamCd'
    });
    $c.bns.fn_SetBnsComboToCode(scwin.vScrenID, dts_Temp, arrCid);
};


/********************************************** 
 * 함수명   	: fn_list_sync
 * 설명       : 리스트 데이터를 조회한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNS_GROUPPING_PACK_ISU_INFO';
    var qryId = 'lds.stf.bnscommon.select.listSelectedIsurNmIsuChg';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    var arrPnl = [pnl_NotAppoint];
    $c.bns.ShowWinArrPnl(arrPnl, grd_List1);
};


/********************************************** 
 * 함수명   	: fn_fee_sync
 * 설명       : 수수료 데이터를 조회한다.
 ***********************************************/
scwin.fn_fee_sync = function() {
    var dsNm = 'BNS_PACK_ANULFEE_INSERT_INFO';
    var qryId = 'lds.stf.bnscommon.select.listSelectedIsurFee';
    var param = '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InputItem, dsNm, qryId, param);
};


/********************************************** 
 * 함수명		: fn_LeftCopy
 * 설명			: 그리드 행 복사 (좌 → 우)
 * argument	: String (One, All)
 ***********************************************/
scwin.fn_LeftCopy = function(Type) {
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if ((Type == 'One') && (dts_List.RowMark(i) == 1)) {
            if (scwin.fn_CopyDuplCheck() == false) return;
            dts_CopyList.insertRow();
            for (var j = 1; j <= dts_List.getTotalCol(); j++) {
                dts_CopyList.setCellData(dts_CopyList.getRowPosition(), j, dts_List.getCellData(i, j));
            }
        }
        if ((Type == 'All')) {
            if (dts_CopyList.getTotalRow() != dts_List.getTotalRow()) {
                dts_CopyList.insertRow();
                for (var j = 1; j <= dts_List.getTotalCol(); j++) {
                    dts_CopyList.setCellData(i, j, dts_List.getCellData(i, j));
                }
            }
        }
    }
};






/********************************************** 
 * 함수명	: fn_CopyDuplCheck	
 * 설명		: 그리드 행 복사 시, 중복체크
 * return	: String
 ***********************************************/
scwin.fn_CopyDuplCheck = function() {
    var curRowVal = dts_List.getCellData(dts_List.getRowPosition(), "BND_APPL_ID");
    for (var i = 1; i <= dts_CopyList.getTotalRow(); i++) {
        if (curRowVal == dts_CopyList.getCellData(i, "BND_APPL_ID")) {
            $c.win.alert("이미 선택된 종목입니다.");
            return false;
        }
    }
};




/********************************************** 
 * 함수명		: fn_RightDel
 * 설명			: 그리드 행 제거
 * argument	: String (One, All)
 ***********************************************/
scwin.fn_RightDel = function(Type) {
    for (var i = 1; i <= dts_CopyList.getTotalRow(); i++) {
        if ((Type == 'All') || (Type == 'One') && (dts_CopyList.RowMark(i) == 1)) {
            if (Type == 'One') $c.cp.removeRow(dts_CopyList, dts_CopyList.getRowPosition());
            if (Type == 'All') dts_CopyList.removeAll();
        }
    }
};




/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if (dts_CopyList.getTotalRow() == 0) {
        $c.win.alert("지정된 종목이 없습니다.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_FeeGrpNm) == '') {
        $c.win.alert("[그룹명]을 입력하십시오.");
        txb_FeeGrpNm.focus();
        return false;
    }
    //자리수 체크		
    if (!$c.stf.checkMaxLength(txb_FeeGrpNm, txb_FeeGrpNm.maxLength, lbl_FeeGrpNm.outerText)) return false;
    if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '비고(사유)')) return false;
    if ($c.stf.getObjectValue(cmb_BndListFeePayYn) == '') {
        $c.win.alert("[신규상장수수료 납부여부]를 선택하십시오.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_BndListFeeExamCd) == "E" && $c.stf.getObjectValue(cmb_BndListFeeExamCd) == '') {
        $c.win.alert("[신규상장수수료 면제사유를 선택하십시오.");
        return false;
    }
    if ($c.stf.getObjectValue(edt_ListFee) == '') {
        $c.win.alert("[신규상장수수료 금액]을 입력하십시오.");
        edt_ListFee.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_YafFeePayYn) == '') {
        $c.win.alert("[연부과금 납부여부]를 선택하십시오.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_YafExamCd) == "E" && $c.stf.getObjectValue(cmb_YafExamCd) == '') {
        $c.win.alert("[연부과금 면제사유를 선택하십시오.");
        return false;
    }
    if ($c.stf.getObjectValue(edt_BndAnulfee) == '') {
        $c.win.alert("[연부과금 수수료 금액]을 입력하십시오.");
        edt_BndAnulfee.focus();
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명		: fn_Insert
 * 설명			: 상장 수수료 그룹핑 등록
 ***********************************************/
scwin.fn_Insert = function() {
    if (scwin.fn_InputCheck() == false) return;
    var vAnswer = confirm('지정된 종목을 수수료 그룹지정 하시겠습니까?');
    if (vAnswer == true) {
        var url = "/bns/ListFeeAndAnulfee.do?method=processPackBndFeeGrpDesign";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = $c.lc.fn_encodeNSession(url);
        trs_Save.KeyValue = "JSP(I:pInput=dts_InputItem, I:pInput2=dts_CopyList)";
        trs_Save.Post();
    }
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Item);
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    $c.bns.BnsPanelToGroupBox(pnl_Group);
    $c.bns.BnsPanelToGroupBox(pnl_Fee);

    //호출파라미터설정
    scwin.fn_SetParam();
    //발행기관 조회
    scwin.fn_SetComboIsurNm();
    //면제사유코드
    scwin.fn_SetComboCode();

    //상장수수료 및 연부과금 면제사유 비활성화
    cmb_BndListFeeExamCd.setDisabled(true);
    cmb_YafExamCd.setDisabled(true);

    //가우스헤더 셋팅(그리드 행 복사 대상)
    dts_CopyList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_GROUPPING_PACK_ISU_INFO";
    dts_CopyList.Reset();
};
scwin.dts_IsurItem_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_IsurItem_OnLoadCompleted = function(rowcount) {
    dts_IsurItem.insertRow(dts_IsurItem.getRowPosition() - 1);
};
scwin.cmb_IsurNm_OnSelChange = function() {
    scwin.vIsurCd = cmb_IsurNm.BindColVal;
    scwin.fn_list_sync();
    scwin.fn_fee_sync();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    var arrPnl = [pnl_NotAppoint];
    $c.bns.CloseWinArrPnl(rowcount, arrPnl, grd_List1);
    dts_CopyList.removeAll();
};
scwin.btn_ToRight_onclick = function() {
    scwin.fn_LeftCopy("One");
};
scwin.btn_ToRightAll_onclick = function() {
    dts_CopyList.removeAll();
    scwin.fn_LeftCopy("All");
};
scwin.btn_ToLeft_onclick = function() {
    scwin.fn_RightDel("One");
};
scwin.btn_ToLeftAll_onclick = function() {
    scwin.fn_RightDel("All");
    //총상장금액 설정
    $c.stf.setObjectValue(txb_TotAmt, '총상장금액 : ' + 0 + ' 원');
};
scwin.img_ListFeeRepayDd_onclick = function() {
    popUpCalendar2(edt_ListFeeRepayDd);
};
scwin.img_AnulfeeRepayDd_onclick = function() {
    popUpCalendar2(edt_AnulfeeRepayDd);
};
scwin.cmb_BndListFeePayYn_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_BndListFeePayYn) == "E") {
        cmb_BndListFeeExamCd.setDisabled(true);
        $c.stf.setObjectValue(edt_ListFee, '0');
    } else {
        cmb_BndListFeeExamCd.setDisabled(true);
        $c.stf.setObjectValue(cmb_BndListFeeExamCd, '');
        if (scwin.vTotAmt != 0) {
            $c.stf.setObjectValue(edt_ListFee, fn_SetComma($c.bns.fn_ListFeeCall(scwin.vTotAmt)));
        }
    }
};
scwin.cmb_YafFeePayYn_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_YafFeePayYn) == "E") {
        cmb_YafExamCd.setDisabled(true);
    } else {
        cmb_YafExamCd.setDisabled(true);
        $c.stf.setObjectValue(cmb_YafExamCd, '');
    }
};
scwin.dts_CopyList_OnLoadCompleted = function(rowcount) {
    if (dts_CopyList.getTotalRow() == 0) {
        //총상장금액 설정
        $c.stf.setObjectValue(txb_TotAmt, '총상장금액 : ' + 0 + ' 원');
    }
    edt_ListFee.RightMargin = 5;
    edt_BndAnulfee.RightMargin = 5;
    edt_ListFeeRepayAmt.RightMargin = 5;
    edt_AnulfeeRepayAmt.RightMargin = 5;
};
scwin.dts_CopyList_OnRowDeleted = function(row) {
    scwin.vTotAmt = dts_CopyList.Sum(2, 1, dts_CopyList.getTotalRow());
    //총상장금액 설정
    $c.stf.setObjectValue(txb_TotAmt, '총상장금액 : ' + fn_SetComma(scwin.vTotAmt) + ' 원');
    //상장수수료 금액 설정
    $c.stf.setObjectValue(edt_ListFee, fn_SetComma($c.bns.fn_ListFeeCall(scwin.vTotAmt)));
};
scwin.dts_CopyList_OnColumnChanged = function(row, colid) {
    scwin.vTotAmt = dts_CopyList.Sum(2, 1, dts_CopyList.getTotalRow());
    //총상장금액 설정
    $c.stf.setObjectValue(txb_TotAmt, '총상장금액 : ' + fn_SetComma(scwin.vTotAmt) + ' 원');
    //상장수수료 금액 설정
    $c.stf.setObjectValue(edt_ListFee, fn_SetComma($c.bns.fn_ListFeeCall(scwin.vTotAmt)));
};
scwin.btn_FeeReg_onclick = function() {
    scwin.fn_Insert();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.edt_ListFee_OnKillFocus = function() {
    edt_ListFee.RightMargin = 5;
};
scwin.edt_BndAnulfee_OnKillFocus = function() {
    edt_BndAnulfee.RightMargin = 5;
};
scwin.edt_ListFeeRepayAmt_OnKillFocus = function() {
    edt_ListFeeRepayAmt.RightMargin = 5;
};
scwin.edt_AnulfeeRepayAmt_OnKillFocus = function() {
    edt_AnulfeeRepayAmt.RightMargin = 5;
};
